import * as THREE from 'three/webgpu';
import {
  uv,
  texture,
  mix,
  MeshBasicNodeMaterial,
} from 'three/tsl';

function createNode(config, ctx) {
  const { atlasRegion } = config;
  const src = atlasRegion.src || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = src.w / src.h; // 512/320 = 1.6

  // Load background texture
  const bgTexture = ctx.textureLoader.load(config.imageUrl);
  bgTexture.wrapS = bgTexture.wrapT = THREE.ClampToEdgeWrapping;
  bgTexture.offset.set(src.x / bgTexture.image.width, 1 - (src.y + src.h) / bgTexture.image.height);
  bgTexture.repeat.set(src.w / bgTexture.image.width, src.h / bgTexture.image.height);

  // Get text texture from font atlas
  const textTexture = ctx.fontAtlas.getTexture({
    text: config.textContent?.[0]?.text || '',
    fontFamily: 'Lora',
    fontWeight: '400',
    fontSize: 39,
    color: config.colors.ink, // '#16161d'
  });
  textTexture.wrapS = textTexture.wrapT = THREE.ClampToEdgeWrapping;
  textTexture.offset.set(0, 0);
  textTexture.repeat.set(1, 1);

  // Build composite material using TSL nodes
  const bgColorNode = texture(bgTexture, uv());
  const textUv = uv().mul(0.85).add(0.075); // centre text in 85% of the plane
  const textColorNode = texture(textTexture, textUv);
  const finalColor = mix(bgColorNode, textColorNode, textColorNode.a);

  const material = new MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  // Plane geometry sized to atlas aspect ratio
  const width = 1.0;
  const height = width / aspect;
  const geometry = new THREE.PlaneGeometry(width, height);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position?.x ?? 0, config.position?.y ?? 0, config.position?.z ?? 0);
  mesh.rotation.set(config.rotation?.x ?? 0, config.rotation?.y ?? 0, config.rotation?.z ?? 0);
  mesh.scale.set(config.scale?.x ?? 1, config.scale?.y ?? 1, config.scale?.z ?? 1);

  // Billboard toward camera every frame
  mesh.userData.handlers = {
    update: (_, camera) => {
      mesh.lookAt(camera.position);
    },
  };

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // textures are cached – no disposal needed
  };

  return mesh;
}

export default createNode;
